const s=v=>String(v==null?'':v).trim();
const vr=$input.first().json.valueRanges;
const C=vr[0].values||[],I=vr[1].values||[],P=vr[2].values||[];
if(C.length<200)throw new Error('ABORT short criteria '+C.length);
if(I.length<200)throw new Error('ABORT short investors '+I.length);
if(P.length<50)throw new Error('ABORT short profile '+P.length);
const ch=C[0].map(s),X={};ch.forEach((k,i)=>X[k]=i);
const ih=I[0].map(s),Z={};ih.forEach((k,i)=>Z[k]=i);
const ph=P[0].map(s),Y={};ph.forEach((k,i)=>Y[k]=i);
const num=v=>{const t=s(v);return t===''?null:(isFinite(Number(t))?Number(t):NaN);};
const critByName={},dupNames=[],blankB=[],rows=[];
for(let i=1;i<C.length;i++){const r=C[i]||[];const g=k=>s(r[X[k]]);
 if(!g('sheet_row')&&!g('investor'))continue;
 const nm=g('investor');
 const o={gridrow:i+1,sheet_row:g('sheet_row'),investor:nm,status:g('status'),mode:g('sector_mode'),sin:g('sectors_in'),smin:g('stage_min'),smax:g('stage_max'),cmin:g('cheque_min_cr'),amin:g('arr_min_cr'),geo:g('geography_scope')};
 rows.push(o);
 if(!nm){blankB.push(i+1);continue;}
 const k=nm.toLowerCase();
 if(critByName[k])dupNames.push(nm+' (rows '+critByName[k].gridrow+','+(i+1)+')');else critByName[k]=o;}
const live=rows.filter(r=>r.status===''||r.status.toUpperCase()==='ACTIVE');
const a=live.filter(r=>!r.smin||!r.smax).map(r=>r.sheet_row+' '+r.investor);
const b=live.filter(r=>r.mode.toUpperCase()==='LIST'&&!r.sin).map(r=>r.sheet_row+' '+r.investor);
const cTxt=live.filter(r=>Number.isNaN(num(r.cmin))||Number.isNaN(num(r.amin))).map(r=>r.sheet_row+' '+r.investor+' cheque='+r.cmin+' arr='+r.amin);
const arrFloor=live.filter(r=>{const v=num(r.amin);return v!==null&&!Number.isNaN(v);});
const geoCount={};live.forEach(r=>{const k=r.geo||'(blank)';geoCount[k]=(geoCount[k]||0)+1;});
const sp=[];
for(let i=1;i<P.length;i++){const r=P[i]||[];const g=k=>s(r[Y[k]]);
 if(!g('startup'))continue;if(g('active').toLowerCase()!=='yes')continue;
 sp.push({row:i+1,startup:g('startup'),arr:g('arr_cr'),basis:g('revenue_basis')});}
const arrBad=sp.filter(x=>{const v=num(x.arr);return v===null||Number.isNaN(v);}).map(x=>x.row+' '+x.startup+' arr='+(x.arr||'(blank)'));
const hasDate=t=>/20\d\d|\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)/i.test(t);
const zeroUndated=sp.filter(x=>num(x.arr)===0&&(!x.basis||!hasDate(x.basis))).map(x=>x.row+' '+x.startup+' basis="'+s(x.basis).slice(0,60)+'"');
const zeroAll=sp.filter(x=>num(x.arr)===0).length;
const noCrit=[],emailMap={};
for(let i=1;i<I.length;i++){const r=I[i]||[];const nm=s(r[Z['investor']]);if(!nm)continue;
 const em=s(r[Z['email']]).toLowerCase();
 if(em){(emailMap[em]=emailMap[em]||[]).push((i+1)+' '+nm);}
 if(!critByName[nm.toLowerCase()])noCrit.push({row:i+1,investor:nm,contact:s(r[Z['contact_person']]),sector:s(r[Z['sector']]).slice(0,70),stage:s(r[Z['stage']]).slice(0,40),cheque:s(r[Z['cheque_inr_cr']]).slice(0,30),dnc:s(r[Z['do_not_contact']])});}
const shared=Object.keys(emailMap).filter(k=>emailMap[k].length>1).map(k=>k+' -> '+emailMap[k].join(' | '));
return [{json:{counts:{criteria_rows:rows.length,investors_rows:I.length-1,profile_active:sp.length,live_criteria:live.length,investors_with_arr_floor:arrFloor.length,startups_arr_zero:zeroAll},a_stage_blank:{n:a.length,list:a},b_list_no_sectors:{n:b.length,list:b},c_text_floors:{n:cTxt.length,list:cTxt},c3_startup_arr_unparseable:{n:arrBad.length,list:arrBad},c4_zero_undated:{n:zeroUndated.length,list:zeroUndated},d_dup_names:{n:dupNames.length,list:dupNames.slice(0,40)},d_blank_investor_col:blankB,geo_values:geoCount,step0b_no_criteria_row:{n:noCrit.length,list:noCrit.slice(0,40)},shared_inboxes:{n:shared.length,list:shared.slice(0,30)}}}];
